package e.e.a;
import java.util.*;import org.json.*;
public final class HistorySortOptionsTest {
 public static class Row {final String id;final Map<String,String> values=new HashMap<>();Row(String id,String title,String stats,String length,long viewed,String posted)throws Exception{this.id=id;values.put("title",title);values.put("videoinfo",stats);values.put("length",length);HistorySupport.captureLocal(this,new JSONObject().put("posttime",viewed).put("postedAt",posted));}public Object a(String key){return values.get(key);}}
 static int checks;static void check(boolean value,String reason){checks++;if(!value)throw new AssertionError(reason);}
 public static void main(String[] args)throws Exception{Row a=new Row("a","Beta","再生:9 コメ:2 マイ:1","0:30",100,"2026-10-03T00:00:00+09:00"),b=new Row("b","Alpha","再生:1 コメ:3 マイ:2","1:00",200,"2026-10-01T00:00:00+09:00"),c=new Row("c","Gamma","再生:5 コメ:1 マイ:3","1:30",300,"2026-10-02T00:00:00+09:00");String[] first={"c","a","a","b","b","c","a","b","b","c","c","a","c","a"},last={"a","c","b","a","c","b","b","a","c","b","a","c","a","c"};for(int mode=0;mode<14;mode++){List<Object> rows=new ArrayList<Object>(Arrays.asList(a,b,c));ListActions.sortRows(rows,mode);check(((Row)rows.get(0)).id.equals(first[mode])&&((Row)rows.get(2)).id.equals(last[mode]),"sort mode "+mode+" has correct direction and field");}check(Arrays.equals(ListActions.sortLabels(false),ListActions.sortLabels(true)),"account and device histories have identical option sets");check(ListActions.sortLabels(false)[0].contains("視聴日時")&&ListActions.sortLabels(false)[1].contains("視聴日時"),"watch time precedes common options");Row unknown=new Row("u","Unknown","","bad",0,"");for(int mode:new int[]{0,1,2,3,6,7,8,9,10,11,12,13}){List<Object> rows=new ArrayList<Object>(Arrays.asList(unknown,a,b));ListActions.sortRows(rows,mode);check(rows.get(2)==unknown,"missing numeric data remains last in mode "+mode);}check(ListActions.length(new Row("h","Hour","","1:02:03",0,""))==3723,"hour duration sorting");check(ListActions.length(new Row("o","Overflow","","999999999999999999999:00",0,""))<0,"invalid duration is missing, not zero");System.out.println("History sort options: "+checks+" field/direction/missing-data checks passed");}
}
